"""Append the executed extension studies to the single existing results report."""
import json
import numpy as np

def extension_rows(P):
 def load(name):return json.loads((P/f'experiments/metrics/{name}.json').read_text())
 rows=['','**Executed extension studies (2026-10-16).** The experiments below are separate from the earlier pilots. Negative and failed outcomes are retained. The full research claim of robust autonomous prediction across shapes and trajectories is not established.']
 if (P/'experiments/metrics/graph_v4_evaluation.json').exists():
  d=load('graph_v4_evaluation');selection=load('graph_study_selection');rows+=['','**Dalton architecture study and updated five-seed ensemble.** All2250 original training geometries; selection remains validation0:16. Three seed11 candidates share the160-epoch maximum schedule; early stopping can shorten actual runs. This screens candidate designs, not a population-level architecture ranking.','','| Candidate | Graph nodes | Parameters | Best selection RMSE(cm) | Epochs completed |','|---|---:|---:|---:|---:|']
  for name,r in selection['candidates'].items():rows.append(f'| {name} | {848 if name=="fine_graph_v4" else 106} | {r["parameters"]} | {r["validation_component_rmse_cm"]:.6f} | {r["epochs_completed"]} |')
  rows+=['',f'Selected {selection["selected"]}, then trained all five seeds. Same503 previously inspected test geometries: mean nodal L2 error {d["mean_nodal_l2_cm"]:.6f}cm versus {d["previous_ensemble_mean_nodal_l2_cm"]:.6f}cm for the previous ensemble ({100*(1-d["mean_nodal_l2_cm"]/d["previous_ensemble_mean_nodal_l2_cm"]):.2f}% lower). Released-model reference remains0.041416cm. Paired mean change {d["paired_mean_nodal_l2_change_cm"]:.6g}cm, conditional geometry-bootstrap95% interval {d["paired_geometry_bootstrap95_change_cm"]}. This is a repeated benchmark comparison, not a new confirmatory test. The accuracy gap to the released model remains.','',f'Updated uncertainty/error Spearman correlation {d["spearman_uncertainty_error"]:.4f}. Historical calibration134 is reused without coverage-based selection. Nominal90/95% joint-geometry coverage: '+', '.join(f'{c["covered"]}/{d["n_test"]} ({c["coverage"]:.2%}), radius{c["radius_cm"]:.4f}cm' for c in d['coverage'])+'.','','![Architecture and repeated benchmark comparison](figures/graph_study.png)']
 if (P/'experiments/metrics/cardiac_geometry_models_v2_evaluation.json').exists():
  d=load('cardiac_geometry_models_v2_evaluation');audit=load('geometry_cohort_audit');manifest=json.loads((P/'experiments/manifests/cardiac_geometry_models_v2.json').read_text());rows+=['','**New mechanics-complete numerical geometry cohort.** 64 independent uniform parameter draws within±5% of the documented ellipsoid radii, plus4 predeclared±10% extrapolation corners. This is a controlled numerical shape distribution from ONE benchmark family, not an anatomical or physiological population. The long axis is X as verified in the source. The original source microstructure algorithm is rerun on every scaled geometry. Exact affine nodal correspondence and unchanged tetrahedral indices are verified.','',f'{audit["n_simulations"]} startup simulations converged on {audit["n_geometries"]} geometries, four prescribed loads each, dt1ms, zero histories/activation. All4577 nodes and17625 tetrahedra retained. Minimum reference endpoint detF {audit["minimum_endpoint_detF"]:.6f}; zero inversions; maximum normalized reference force RMS {audit["maximum_reference_normalized_residual_rms"]:.3g}; no exact duplicate parameter draws. Small perturbations deliberately create closely related shapes.','', 'Geometry splits:20 training(80 loads),8 selection(32),20 calibration(80),16 test(64),4 extrapolation(16). Every load from a geometry stays in its split. This cohort has no historical calibration/test reuse. Train-only normalizers and rank12 POD use only the80 training fields. The graph encoder has64 pooled nodes, width32 and two message-passing rounds; a geometry/load-conditioned neural head predicts POD coefficients. Correspondence is specific to this affine family.','',f'Five matched seeds,800 optimizer updates per model. Physics lambda screened at1/100 on seed11, then frozen at {manifest["lambda_selection"]["lambda"]:g} using trusted float64 validation residuals subject to a10% displacement-RMSE constraint. Optimization/checkpoint scoring used the verified float32 GPU residual; final evaluation uses float64 arithmetic and trusted FE assembly. The CPU pilot and interrupted screening arm are preserved in cpu_geometry_pilot.json.','','| Five-member ensemble | Mean geometry component RMSE(µm) | Mean normalized force RMS | Mean element strain error | Mean relative elastic-energy error |','|---|---:|---:|---:|---:|']
  for label,r in d['models'].items():
   t=r['splits']['test'];g=t['per_geometry'];rows.append(f'| {label} | {t["mean_component_rmse_m"]*1e6:.6f} | {t["mean_normalized_residual_rms"]:.8g} | {np.mean([v["mean_strain_frobenius_error"] for v in g]):.6g} | {np.mean([v["mean_relative_elastic_energy_error"] for v in g]):.6g} |')
  rows+=['',f'H1 is not supported in this startup study. Physics/data displacement-RMSE ratio {d["ensemble_displacement_RMSE_ratio"]:.6f}; paired mean normalized residual difference(physics minus data) {d["paired_ensemble_residual_difference"]:.6g}, conditional geometry-bootstrap95% interval {d["paired_geometry_bootstrap95_residual_difference"]}. The approximately0.12% residual difference is small; it does not show a useful physics benefit. Bootstrap intervals condition on trained models and exclude retraining/implementation uncertainty. Individual matched-seed outcomes are in the JSON.','', '**Natural-boundary ablation.** All DOFs are free. Interior and boundary-DOF contributions partition the SAME full assembled weak residual, including inertia, viscosity, Robin terms and follower pressure; their losses sum exactly when normalized by total DOFs. Boundary-DOF loss is not a claim that external traction alone should vanish. Ablations use one matched seed only.','','| Seed11 residual-loss region | Test component RMSE(µm) | Mean normalized FULL residual RMS |','|---|---:|---:|']
  for region,r in d['natural_boundary_interior_ablations_single_seed'].items():rows.append(f'| {region} | {r["mean_component_rmse_m"]*1e6:.6f} | {r["mean_normalized_full_residual_rms"]:.8g} |')
  rows+=['','**Independent geometry calibration.** The simultaneous score is the maximum nodal L2 displacement error over ALL nodes AND ALL four loads in a geometry. Corrected split-conformal quantiles use20 calibration geometries. Exchangeability refers only to the defined uniform numerical parameter distribution.','','| Ensemble | Nominal | Joint test coverage | Radius(µm) | Exact binomial95% interval |','|---|---:|---:|---:|---|']
  for label,r in d['models'].items():
   for c in r['splits']['test']['coverage']:rows.append(f'| {label} | {c["nominal"]:.0%} | {c["covered"]}/{c["n_geometries"]} ({c["coverage"]:.2%}) | {c["radius_m"]*1e6:.4f} | {c["binomial95"]} |')
  rows+=['','The16 test geometries give wide coverage intervals. Raw variance/error Spearman correlation was0.75 for both ensembles; selective-risk results are in the per-model JSON. This does not make raw variance a calibrated interval.','', '**Observed shift failure:** both nominal90% and95% balls covered0/4 extrapolation geometries for both models. Mean nodal error increased from about0.35µm in distribution to3.64µm at the shifted corners. The four deterministic corners have no exchangeability-based coverage guarantee and do not support a population-level shift estimate. H3 is not supported.','','![Geometry mechanics and uncertainty comparison](figures/geometry_study.png)','','![Actual FE boundary prediction and error](figures/geometry_prediction.png)']
 if (P/'experiments/metrics/trajectory_validation.json').exists():
  d=load('trajectory_validation');meta=load('cardiac_passive_trajectory_v1');rows+=['','**Full passive reference trajectory and temporal sensitivity.** A pressure-only variant of the pinned dynamic benchmark, with P1 displacement/fibers, zero activation and initial u/v/a=0. Generalized-alpha histories are updated after every converged solve; pressure is evaluated at the source intermediate time. This differs from the default active/P2 benchmark.','',f'{meta["completed_steps"]}/{meta["n_steps"]} steps completed over0.001–0.999s, dt1ms; minimum endpoint detF {d["minimum_detF"]:.6f}, zero inverted elements across all stored states. Measured FE trajectory wall time {meta["seconds"]:.1f}s. The40ms endpoint volume-L2 differences versus dt0.5ms were {100*d["time_sensitivity"][-1]["dt001_relative_volume_L2_difference_vs_dt0005"]:.5f}% for dt1ms and {100*d["time_sensitivity"][-1]["dt002_relative_volume_L2_difference_vs_dt0005"]:.5f}% for dt2ms. This short-interval check does not prove full-cycle timestep convergence. Earlier two-level mesh sensitivity also does not establish mesh independence.','','![Reference trajectory and timestep sensitivity](figures/trajectory_validation.png)']
 if (P/'experiments/metrics/cardiac_temporal_balanced_v2_evaluation.json').exists():
  d=load('cardiac_temporal_balanced_v2_evaluation');selection=json.loads((P/'experiments/manifests/cardiac_temporal_balanced_v2_selection.json').read_text());rows+=['','**Temporal neural pilot, with explicit rollout failure.** One fixed geometry and one cycle. Train first600 timesteps, select on next200, evaluate last199. A64/64 MLP with train-only rank16 POD predicts acceleration increments from causal displacement/velocity/acceleration histories and prescribed pressure. Exact Newmark updates produce the displacement prediction. Matched seed11 and400 updates per condition. Time frames are dependent: no geometry/trajectory confidence interval or conformal claim is made.','', 'The original lambda1/100 grid had little effect. A training-only parameter-gradient diagnostic on eight training frames registered the balanced grid1e5/1e6/1e7, then validation selected1e6. The same temporal block had already been evaluated by the original pilot; the balanced comparison is exploratory repeated temporal evaluation. No test outcome selected the grid.','','| Model | True-history one-step component RMSE(µm) | Mean normalized force RMS | Recursive valid steps /199 | First invalid-J time(s) |','|---|---:|---:|---:|---:|']
  for label,r in d['models'].items():rows.append(f'| {label} | {r["teacher_forced_component_rmse_m"]*1e6:.6f} | {r["teacher_forced_mean_normalized_residual_rms"]:.8g} | {r["rollout_steps_completed"]}/199 | {r["failure"]["time_s"] if r["failure"] else "none"} |')
  rows+=['','With true histories supplied, balanced physics weighting reduced conditional one-step displacement error by about9.0% and force residual by24.1%. BOTH recursive rollouts failed with inverted elements: physics after25 valid steps and data-only after28. Valid-prefix errors use different horizons and must not be interpreted as successful or directly comparable complete rollouts. The temporal model is not a validated autonomous full-cycle predictor. Scaling to a multi-geometry trajectory cohort is a no-go until closed-loop stability is addressed.','','![One-step gains and recursive failures](figures/temporal_study.png)']
 if (P/'experiments/metrics/geometry_runtime.json').exists():
  d=load('geometry_runtime');rows+=['','**Matched speed and cost.** CPU float64, two threads, same P1 startup task, four held-out numerical geometries×four loads. Neural inference returns the full4577×3 field.','',f'Warm FE median {d["warm_FE_solver"]["median_ms"]:.3f}ms, five-member ensemble median {d["nn_five_member_ensemble"]["median_ms"]:.3f}ms: {d["warm_median_speedup_ensemble"]:.1f}× for this startup task. Batch-one repetitions:32 timed FE solves and800 ensemble calls. No full-cycle, Dalton or clinical speedup follows. Input preprocessing, model load and geometry activation are recorded separately in geometry_runtime.json. Fiber-field generation is excluded from the resident-input inference comparison.','',f'New cohort generation wall time {d["corpus_generation_wall_seconds"]:.1f}s; GPU study training/validation grid plus ablations {d["all_gpu_study_training_validation_seconds"]:.1f}s. Measured partial-cost recovery about{d["measured_cost_recovery_query_count"]:.0f} comparable queries. This excludes the CPU pilot, verification, temporal experiments, preprocessing and software setup; it is not whole-project break-even.']
 if (P/'experiments/metrics/neural_physics_gradient.json').exists():
  g=load('neural_physics_gradient');rows+=['',f'Physics-only backpropagation through an actual trained graph/POD model was verified: parameter-gradient norm {g["physics_only_parameter_gradient_norm"]:.6g}; relative difference versus native float64 VJP through the same network graph {g["relative_difference_vs_native_VJP_through_same_network_graph"]:.3g}. Independent assembly checks include nonzero histories and a strongly deformed state. GPU optimization uses float32 after controlled precision checks; final mechanics uses float64.']
 rows+=['','**Go/no-go and reproducibility.** No external data/solver blocker remains for these numerical studies. The scientific blockers are the remaining released-model accuracy gap, no useful startup physics advantage, shift undercoverage and unstable recursive dynamics. The next experiment should train for closed-loop stability and test on independent trajectories before scaling the full trajectory cohort. Independent anatomical sources and full-cycle mesh/timestep convergence remain unvalidated.','', 'Reproduce the extensions with `make graph-study`, `make geometry-study`, `make temporal-study` and `make report` after the original data/environment setup. Runtime requires the legacy solver environment; MPS training requires Apple GPU access. Configs, split IDs, checkpoint hashes, per-geometry/seed results and failed-rollout artifacts are retained. Large datasets/checkpoints/logs remain ignored.','', 'Official conference requirements were verified and checksummed in experiments/manifests/conference.json: [CMBBE2027 submission page](https://www.cmbbe-symposium.com/2027/abstract-submission/). The mandatory template is one A4 page in two columns, including figures/references; deadline15November2026 at23:59CET. No manuscript or submission was created, respecting the user request to exclude paper/.','']
 return rows
